from lib import *
S = SS('n49')
steps = [
    step("最常用的写法:httptest.NewRecorder() 加 r.ServeHTTP(w, req),不起端口。GET /users/42?q=x 得到状态 200、Content-Type: application/json; charset=utf-8、中间件设的 X-MW=1,body 里 full=/users/:id、id=42、ip=192.0.2.1;httptest.NewRequest 的默认值:Host=example.com、RemoteAddr=192.0.2.1:1234、Proto=HTTP/1.1(所以测试里 ClientIP 总是 192.0.2.1);POST 不设 Content-Type 时 ShouldBindJSON 仍按 JSON 解码(201);坏 JSON → 400,错误是 invalid character 'b' looking for beginning of object key string。注意 setup 用了 gin.Default(),所以测试输出里有 5 行 [GIN-debug]。", t=tl(S(1)), mark=lidx(S(1), 'NewRecorder:状态 200', 'RemoteAddr="192.0.2.1:1234"', '坏 JSON'), done=lidx(S(1), 'POST 没设 Content-Type', '[GIN-debug] GET    /users/:id'), kv=KV([['NewRecorder + ServeHTTP', '不起端口,最快'], ['默认 RemoteAddr', '192.0.2.1:1234,ClientIP 为 192.0.2.1'], ['gin.Default()', '测试输出里有 [GIN-debug] 噪音']], ['默认 RemoteAddr'])),
    step("gin.CreateTestContext(w) 返回 (*Context, *Engine),但 Context 是“空壳”:c.Request 为 nil、c.Params 为空、c.FullPath() 为空、引擎里没有路由。直接调用 handler 访问 c.Request 会 nil pointer panic;设了 Request 之后 c.Param(\"id\") 仍是空串({\"id\":\"\",\"path\":\"/users/7\"});手工 c.Params = gin.Params{{Key: \"id\", Value: \"7\"}} 之后才得到 {\"id\":\"7\"};c.Set / c.Get 可用;没有 handler 链,c.Next() 什么都不做。适合单独测一个 handler 函数,不适合测路由与中间件。", t=tl(S(2)), mark=lidx(S(2), 'panic: runtime error: invalid memory address', '设了 Request 但 c.Param("id") 为空'), done=lidx(S(2), 'CreateTestContext:c.Request==nil true', '手工设置 c.Params 之后', 'c.Set / c.Get 可用'), kv=KV([['c.Request', 'nil,要自己设'], ['c.Params', '空,路径参数要手工设'], ['路由 / 中间件', '没有,CreateTestContext 不测它们']], ['c.Params'])),
    step("记录器与真实服务器的差别:/late 先写 body 再设 X-Late。httptest 记录器的 w.Header()(活的 map)里能看到 X-Late=1;w.Result().Header(响应快照)里是空;真实服务器加真实 HTTP 客户端同样是空。所以只用 w.Header() 断言,会让“写出之后才设的头”这类 bug 的测试通过——要断言 w.Result().Header 或用 httptest.NewServer。", t=tl(S(3)), mark=lidx(S(3), 'X-Late="1"'), done=lidx(S(3), '真实服务器 + 真实客户端'), kv=KV([['w.Header()', '活的 map,包含写出之后设的头'], ['w.Result().Header', '快照,与真实客户端一致'], ['结论', '断言头要用 Result()']], ['结论'])),
    step("go test 里 gin.Mode() 默认是 debug(不设置 GIN_MODE 时),所以 gin.Default() / gin.New() 会输出一堆 [GIN-debug] 警告;在 TestMain 里 gin.SetMode(gin.TestMode) 之后,同一个测试的输出只剩 5 行(=== RUN、日志、--- PASS、PASS、ok)。", t=tl(S(4)), mark=lidx(S(4), 'gin.Mode()="test"', '加了 TestMain'), done=lidx(S(4), 'gin.Mode()="debug"'), kv=KV([['默认', 'go test 里是 debug,输出很吵'], ['TestMain', 'gin.SetMode(gin.TestMode)'], ['注意', 'CreateTestContext 也会输出调试警告']], ['TestMain'])),
    step("一次请求的耗时:NewRecorder + NewRequest + ServeHTTP 约 2.1 µs;真实回环 HTTP(httptest.NewServer + keep-alive 的 http.Client)约 53.1 µs,大约 25 倍。大量请求的测试用 ServeHTTP 快得多;需要真实网络行为(超时、断开、HTTP/2、响应头真正发出)才用 NewServer。", t=tl(S(5)), mark=lidx(S(5), 'NewRecorder + NewRequest', '真实 HTTP'), b=bars([['ServeHTTP + 记录器', 2.1, '2.1 µs'], ['真实回环 HTTP', 53.1, '53.1 µs']], 53.1, done=[0], mark=[1]), kv=KV([['ServeHTTP', '约 2 µs,适合大量用例'], ['真实 HTTP', '约 53 µs,适合网络行为'], ['选择', '先 ServeHTTP,必要时 NewServer']], ['选择'])),
]
A = mkartn('n49', 49, 'Gin,测试,httptest,CreateTestContext,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测测试写法:NewRecorder + ServeHTTP 的默认值(RemoteAddr 192.0.2.1);CreateTestContext 的 Context 没有 Request、Params 与路由;记录器的 w.Header() 能看到写完才设的头,而 Result() 与真实客户端看不到;go test 里默认是 debug 模式;ServeHTTP 约 2.1 µs,真实 HTTP 约 53.1 µs。',
    '给 Gin 写测试,是用 httptest.NewRecorder 还是 gin.CreateTestContext?它们各自缺什么、会让哪些 bug 逃过测试、哪些情况必须起真实服务器?这篇用一个小应用跑真实的 go test,把它们的行为和耗时逐项对出来。',
    [('2.1 vs 53.1 µs', '一次请求:ServeHTTP + 记录器 与真实回环 HTTP 的耗时(约 25 倍)'), ('c.Param 为空', 'CreateTestContext 的 Context 没有 Params,getUser 输出 id="",手工设置 c.Params 后才是 "7"'), ('X-Late', '记录器 w.Header() 能看到写完才设的头;w.Result().Header 与真实客户端看不到')],
    [('NewRecorder + ServeHTTP', '<p>这是测路由、中间件、绑定、响应的首选:引擎真实地走完整条链,只是不经过网络。注意 <code>httptest.NewRequest</code> 的默认 RemoteAddr 是 <code>192.0.2.1:1234</code>,所以依赖 ClientIP 的逻辑(限流、白名单)在测试里看到的总是这个地址,需要时手工设置 <code>req.RemoteAddr</code>。</p>'),
     ('CreateTestContext', '<p>得到的是一个空的 Context:没有 Request、没有路径参数、没有路由。适合直接调用单个 handler 函数(先设好 Request,必要时手工设 <code>c.Params</code>),不适合测路由匹配和中间件顺序——那些要用上面的方式。</p>'),
     ('记录器的盲区', '<p><code>ResponseRecorder.Header()</code> 返回的是活的 map,写出之后再改的头也能看到;真实服务器里这些头根本发不出去。想断言“客户端会看到什么”,用 <code>w.Result().Header</code>,或者起 <code>httptest.NewServer</code>。超时、客户端断开、HTTP/2、真实的 <code>Hijack</code> 也只有真实服务器才测得出来。</p>'),
     ('测试模式', '<p>go test 里不设置 <code>GIN_MODE</code> 时 Gin 是 debug 模式,每次创建引擎都会输出警告和路由表。在 <code>TestMain</code> 里 <code>gin.SetMode(gin.TestMode)</code> 就安静了。</p>'),
     ('速度', '<p>进程内的 <code>ServeHTTP</code> 只要几微秒,几千个用例也是毫秒级;真实 HTTP 约慢 25 倍,但仍然是几十微秒,所以是否起服务器应该由“要不要测网络行为”决定,而不是性能。</p>')],
    steps,
    [ENV_N_GIN + '。第一到四节是真实的 go test -v(每个实验单独用 -run 运行,Go 1.27.1,测试包名为 lab);第五节用 testing.Benchmark 的 5 轮中位数;第三节的真实服务器是 httptest.NewServer,客户端是 http.Get;每种情形各一次',
     '没有验证:并行测试(t.Parallel)下共享引擎的并发安全(ServeHTTP 本身可并发,没有用 -race 测);表驱动测试的写法(只是风格);gin.CreateTestContextOnly 等其它辅助函数(源码里有,没有试);Mock 数据库等依赖的方式;测试覆盖率工具'],
    '测试')
